mod = 1000000007
factlist = [1]
for i in range(1, 1000001):
	factlist.append(factlist[-1] * i % mod)
factinvlist = [0] * len(factlist)
factinvlist[-1] = pow(factlist[-1], mod - 2, mod)
for i in range(len(factlist) - 1, 0, -1):
	factinvlist[i - 1] = factinvlist[i] * i % mod
t = int(input())
for _ in range(t):
	[n, m, k, mod2] = list(map(int, input().split()))
	if n == m:
		print(1 % mod2)
		continue
	multtrees = factinvlist[:k + 1] + [0] * ((m - 1) * k)
	reptrees = [1] + [0] * (m * k)
	curr = m
	while curr > 0:
		if curr % 2:
			for i in range(m * k, -1, -1):
				for j in range(i):
					reptrees[i] += reptrees[j] * multtrees[i - j]
				reptrees[i] = reptrees[i] % mod
		for i in range(m * k, -1, -1):
			for j in range(i):
				multtrees[i] += multtrees[j] * multtrees[i - j]
			multtrees[i] = multtrees[i] % mod
		curr //= 2
	altn = n - m
	toprint = 0
	for i in range(1, min(altn, m * k) + 1):
		toprint += reptrees[i] * i * factinvlist[n - m - i] * pow(altn, altn - i - 1, mod)
	print(toprint * factlist[n] * factinvlist[m] % mod % mod2)
